local CoinSorterMaker = {}
local PRODUCTS = {
    iron_coin_sorter = { name = "Železno sortiralce kovancev", ironCost = 4, woodCost = 2, leatherCost = 1, time = 5, cost = 180, prestige = 4, happiness = 2, description = "Železno sortiralce za razvrščanje kovancev." },
    bronze_coin_sorter = { name = "Bronasto sortiralce kovancev", bronzeCost = 4, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 435, prestige = 6, happiness = 3, description = "Bronasto sortiralce za hitro razvrščanje." },
    silver_coin_sorter = { name = "Srebrno sortiralce kovancev", silverCost = 4, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 1050, prestige = 11, happiness = 4, description = "Srebrno sortiralce za plemiške zakladnike." },
    gilded_coin_sorter = { name = "Pozlačeno sortiralce kovancev", goldCost = 1, silverCost = 4, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 2250, prestige = 20, happiness = 5, description = "Pozlačeno sortiralce za dvorne zakladnike." },
    jewel_set_coin_sorter = { name = "Draguljasto sortiralce kovancev", goldCost = 2, silverCost = 4, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4850, prestige = 36, happiness = 7, description = "Draguljasto sortiralce za kraljevske zakladnike." },
    royal_sovereign_coin_sorter = { name = "Kraljevski suvereno sortiralce kovancev", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 10400, prestige = 69, happiness = 13, description = "Suvereno sortiralce z biseri za krono." },
}
local BUILDINGS = {
    coinsorter_workshop = { name = "Sortiralna delavnica", cost = { gold = 365, wood = 180, stone = 145, iron = 9 }, upkeep = 7, qualityBonus = 5 },
    coinsorter_house = { name = "Sortiralna hiša", cost = { gold = 1285, wood = 365, stone = 290, silver = 8, iron = 8 }, upkeep = 27, qualityBonus = 18 },
    master_coinsorter_atelier = { name = "Mojstrski sortiralni atelje", cost = { gold = 3200, wood = 425, stone = 545, silver = 39, gold = 8 }, upkeep = 75, qualityBonus = 30 },
    sovereign_coinsorter_palace = { name = "Suverena sortiralna palača", cost = { gold = 13600, wood = 655, stone = 860, gold = 88, jewel = 20 }, upkeep = 263, qualityBonus = 55, prestigeBonus = 50 },
}
CoinSorterMaker.ironStock = 16; CoinSorterMaker.bronzeStock = 14; CoinSorterMaker.woodStock = 12; CoinSorterMaker.leatherStock = 10; CoinSorterMaker.silverStock = 8; CoinSorterMaker.goldStock = 6; CoinSorterMaker.jewelStock = 4; CoinSorterMaker.pearlStock = 4
CoinSorterMaker.productStock = {}; CoinSorterMaker.buildings = {}; CoinSorterMaker.maker = nil; CoinSorterMaker.activeMaking = {}; CoinSorterMaker.totalProducts = 0; CoinSorterMaker.dayTimer = 0
function CoinSorterMaker.init() CoinSorterMaker.ironStock=16; CoinSorterMaker.bronzeStock=14; CoinSorterMaker.woodStock=12; CoinSorterMaker.leatherStock=10; CoinSorterMaker.silverStock=8; CoinSorterMaker.goldStock=6; CoinSorterMaker.jewelStock=4; CoinSorterMaker.pearlStock=4; CoinSorterMaker.productStock={}; CoinSorterMaker.buildings={}; CoinSorterMaker.maker=nil; CoinSorterMaker.activeMaking={}; CoinSorterMaker.totalProducts=0; CoinSorterMaker.dayTimer=0; print("[CoinSorterMaker] Royal Coin Sorter Maker System initialized (6 products, 4 buildings)") end
function CoinSorterMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CoinSorterMaker.maker={name=n or ("Sortiralec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sortiralec najet: %s (spretnost: %d)",CoinSorterMaker.maker.name,s),"success") end; return true end
function CoinSorterMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CoinSorterMaker.build(id) local ok,e=CoinSorterMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CoinSorterMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CoinSorterMaker.getQualityBonus() local b=0; for _,bd in ipairs(CoinSorterMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CoinSorterMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and CoinSorterMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and CoinSorterMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and CoinSorterMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and CoinSorterMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and CoinSorterMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CoinSorterMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CoinSorterMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CoinSorterMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CoinSorterMaker.buildings==0 then return false,"Potrebna sortiralna delavnica" end; if not CoinSorterMaker.maker then return false,"Potreben sortiralec" end; return true end
function CoinSorterMaker.make(pt,qty) qty=qty or 1; local ok,e=CoinSorterMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then CoinSorterMaker.ironStock=CoinSorterMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then CoinSorterMaker.bronzeStock=CoinSorterMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then CoinSorterMaker.woodStock=CoinSorterMaker.woodStock-d.woodCost*qty end; if d.leatherCost then CoinSorterMaker.leatherStock=CoinSorterMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then CoinSorterMaker.silverStock=CoinSorterMaker.silverStock-d.silverCost*qty end; if d.goldCost then CoinSorterMaker.goldStock=CoinSorterMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CoinSorterMaker.jewelStock=CoinSorterMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CoinSorterMaker.pearlStock=CoinSorterMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CoinSorterMaker.maker then t=math.max(1,t-math.floor(CoinSorterMaker.maker.skill/13)) end; table.insert(CoinSorterMaker.activeMaking,{id="coinsorter_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CoinSorterMaker.completeMaking(m) local q=1.0+(CoinSorterMaker.getQualityBonus()/100); if CoinSorterMaker.maker then q=q+(CoinSorterMaker.maker.skill/140) end; q=math.min(2.5,q); CoinSorterMaker.productStock[m.productType]=(CoinSorterMaker.productStock[m.productType] or 0)+m.quantity; CoinSorterMaker.totalProducts=CoinSorterMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CoinSorterMaker.maker then CoinSorterMaker.maker.itemsMade=CoinSorterMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CoinSorterMaker.maker.skill=math.min(100,CoinSorterMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sortiralec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"coinsorter.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function CoinSorterMaker.update(dt) if not _G.state then return end; CoinSorterMaker.dayTimer=CoinSorterMaker.dayTimer+dt; if CoinSorterMaker.dayTimer>=30 then CoinSorterMaker.dayTimer=0; for i=#CoinSorterMaker.activeMaking,1,-1 do local m=CoinSorterMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CoinSorterMaker.completeMaking(m); table.remove(CoinSorterMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CoinSorterMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CoinSorterMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CoinSorterMaker.getStats() return {ironStock=CoinSorterMaker.ironStock,bronzeStock=CoinSorterMaker.bronzeStock,woodStock=CoinSorterMaker.woodStock,leatherStock=CoinSorterMaker.leatherStock,silverStock=CoinSorterMaker.silverStock,goldStock=CoinSorterMaker.goldStock,jewelStock=CoinSorterMaker.jewelStock,pearlStock=CoinSorterMaker.pearlStock,productStock=CoinSorterMaker.productStock,numBuildings=#CoinSorterMaker.buildings,hasMaker=CoinSorterMaker.maker~=nil,makerName=CoinSorterMaker.maker and CoinSorterMaker.maker.name or "—",makerSkill=CoinSorterMaker.maker and CoinSorterMaker.maker.skill or 0,activeMaking=#CoinSorterMaker.activeMaking,totalProducts=CoinSorterMaker.totalProducts} end
return CoinSorterMaker
